import type { ReactNode } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Chip } from "@/shared/ui/data/Chip";
import { KeyValueList } from "@/shared/ui/data/KeyValueList";
import { PageHeader } from "@/shared/ui/pages/PageHeader";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";

function SectionLabel({ children }: { children: ReactNode }) {
  return <div className="mono" style={{ fontSize: 10, letterSpacing: ".06em", textTransform: "uppercase", color: "var(--fg-dim)" }}>{children}</div>;
}

export type ChipTone = "neutral" | "accent" | "success" | "info" | "danger";
export interface RecordSection {
  label: string;
  entries: { k: ReactNode; v: ReactNode }[];
}
export interface RecordPageProps {
  title?: ReactNode;
  subtitle?: ReactNode;
  status?: string;
  statusTone?: ChipTone;
  actions?: ReactNode;
  sections?: RecordSection[];
  aside?: ReactNode;
  asideWidth?: number;
  className?: string;
  loading?: boolean;
}
const DEMO_SECTIONS: RecordSection[] = [
  { label: "Session", entries: [{ k: "model", v: "opus" }, { k: "role", v: "worker" }] },
  { label: "Worktree", entries: [{ k: "branch", v: "2409-name-derived-key" }] },
];
export function RecordPage({
  title = "api-builder", subtitle, status = "running", statusTone = "success", actions,
  sections = DEMO_SECTIONS, aside, asideWidth = 300, className, loading = false,
}: RecordPageProps) {
  const resolvedAsideWidth = Math.min(Math.max(asideWidth, 160), 480);
  const heading = status != null ? (
    <Row gap={8} inline>
      {title}
      <Chip size="xs" tone={statusTone}>{status}</Chip>
    </Row>
  ) : title;

  return (
    <Stack gap={0} className={className} style={{ flex: 1, minHeight: 0, overflow: "hidden" }}>
      <PageHeader title={heading} hint={subtitle} toolbar={actions} />
      <Row gap={0} align="stretch" style={{ flex: 1, minHeight: 0 }}>
        <Box pad={16} style={{ flex: 1, minWidth: 0, overflowY: "auto" }}>
          {loading ? (
            <Stack gap={20}>
              {Array.from({ length: 2 }).map((_, si) => (
                <Stack key={si} gap={10}>
                  <Skeleton w={90} h={9} />
                  <Stack gap={7}>{Array.from({ length: 3 }).map((__, ri) => <Skeleton key={ri} h={11} w={ri === 2 ? "50%" : "85%"} />)}</Stack>
                </Stack>
              ))}
            </Stack>
          ) : sections.length > 0 ? (
            <Stack gap={20}>
              {sections.map((s) => (
                <Stack key={s.label} gap={10}>
                  <SectionLabel>{s.label}</SectionLabel>
                  <KeyValueList items={s.entries} />
                </Stack>
              ))}
            </Stack>
          ) : (
            <EmptyState title="No fields yet" description="Sections appear here as the record's fields fill in." />
          )}
        </Box>
        {aside != null && (
          <Box pad={16} style={{ width: resolvedAsideWidth, maxWidth: "45%", flex: "0 0 auto", minWidth: 0, overflowY: "auto", borderLeft: "1px solid var(--border-soft)" }}>
            {aside}
          </Box>
        )}
      </Row>
    </Stack>
  );
}

